import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import ScheduleTable from "../../components/ScheduleTable/ScheduleTable"; // Componenta pentru tabelă
import OrarStudenti from './OrarStudenti';  
import OrarProfesori from './OrarProfesori';  
import OrarDiscipline from './OrarDiscipline';  
import OrarSali from './OrarSali';  
import "./OrarToti.css";

const OrarToti = () => {
  const navigate = useNavigate();
  const { an, grupa, profesor, section } = useParams(); // Adăugăm `profesor` în params

  const [selectedGroup, setSelectedGroup] = useState(null);
  const [scheduleData, setScheduleData] = useState([]);
  const [currentSection, setCurrentSection] = useState(section || "studenti");

  // Se actualizează dacă an și grupa sunt disponibile
  useEffect(() => {
    if (profesor) {
      // Dacă există un profesor selectat, preluăm orarul acestuia
      const url = `http://localhost:34101/orar/profesor/${profesor}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          setScheduleData(data);
        })
        .catch((err) => {
          console.error("Eroare la preluarea orarului profesorului:", err);
        });
    } else if (an && grupa) {
      // Dacă există an și grupă, preluăm orarul pentru grupă
      const anLabel = `Anul ${an}`;
      setSelectedGroup(`${anLabel} - ${grupa}`);
      setCurrentSection("studenti");

      const url = `http://localhost:34101/orar/grupa/${an}/${grupa}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          setScheduleData(data);
        })
        .catch((err) => {
          console.error("Eroare la preluarea orarului:", err);
        });
    }
  }, [profesor, an, grupa]);

  // Funcția de navigare înapoi la pagina principală de secțiune (studenti, profesori, etc.)
  const handleBackButtonClick = () => {
    setSelectedGroup(null);
    setScheduleData([]);
    navigate(`/app/orar/${currentSection}`);  // Navighează către secțiunea principală
  };

  const handleSectionChange = (newSection) => {
    setCurrentSection(newSection);
    navigate(`/app/orar/${newSection}`);
  };

  return (
    <div className="orar-container">
      {scheduleData.length > 0 ? (
        <div className="orar-afisat">
          <h3>
            {profesor
              ? `Orar pentru Profesorul ${profesor}`
              : `Orar pentru ${selectedGroup}`}
          </h3>
          <ScheduleTable
            schedule={scheduleData}
            title={profesor ? `Orar pentru Profesorul ${profesor}` : `Orar pentru ${selectedGroup}`}
          />
          <button
            className="orar-button inapoi"
            onClick={handleBackButtonClick}
          >
            🔙 Înapoi
          </button>
        </div>
      ) : (
        <h2>Se încarcă orarul...</h2>
      )}

      {!scheduleData.length && !profesor && (
        <>
          <div className="orar-titlu">
            <h1>Orar</h1>
            {!currentSection && <h2>Alege o categorie</h2>}
            {currentSection === "studenti" && <h2>Alege anul și grupa</h2>}
            {currentSection === "profesori" && <h2>Alege profesorul</h2>}
          </div>

          {!currentSection && (
            <div className="orar-buttons">
              <button
                className="orar-button"
                onClick={() => handleSectionChange("studenti")}
              >
                🎓 Orar Studenți
              </button>
              <button
                className="orar-button"
                onClick={() => handleSectionChange("profesori")}
              >
                👨‍🏫 Orar Profesori
              </button>
              <button
                className="orar-button"
                onClick={() => handleSectionChange("sali")}
              >
                🏫 Orar Săli
              </button>
              <button
                className="orar-button"
                onClick={() => handleSectionChange("discipline")}
              >
                📚 Orar Discipline
              </button>
            </div>
          )}

          {currentSection === "studenti" && (
            <>
              <div className="orar-buttons">
                <button
                  className="orar-button inapoi"
                  onClick={handleBackButtonClick}
                >
                  🔙 Înapoi la Orar
                </button>
              </div>
              <OrarStudenti />
            </>
          )}
          {currentSection === "profesori" && <OrarProfesori />}
          {currentSection === "discipline" && <OrarDiscipline />}
          {currentSection === "sali" && <OrarSali />}
        </>
      )}
    </div>
  );
};

export default OrarToti;
